/* Financial snapshots retain each issuer's reporting basis and profit definition. */
window.companyFinancials=(()=>{
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=new Intl.NumberFormat('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2});
 const amount=value=>number.format(value);
 function render(c){
  const f=window.COMPANY_FINANCIALS?.[c.id];
  if(!f)return `<section class="financial-panel financial-pending" id="financials" aria-labelledby="financial-title"><div class="eyebrow">FINANCIAL BREAKDOWN · AWAITING VERIFICATION</div><h3 id="financial-title">A business split still needs checking.</h3><p>Revenue and profit figures have not yet been verified for this profile. This does not mean the company does not disclose them.</p><p class="source-note">We will show a business split only after checking its reporting period, units and profit definition. Individual brands may not have separately disclosed profits.</p><a href="#sources" data-scroll="sources">Explore the original company sources ↓</a></section>`;
  const margin=f.profitKind==='margin';
  const revenueLabel=f.revenueLabel||'Revenue';
  const incomeDefinition=f.incomeDefinition||'Revenue is sales before costs.';
  const maxRevenue=Math.max(1,...f.rows.map(r=>r.revenue));
  const amountScale=Math.max(maxRevenue,...f.rows.map(r=>Math.abs(r.profit||0)));
  const resultScale=margin?100:amountScale;
  const largestSales=f.rows.reduce((a,b)=>a.revenue>=b.revenue?a:b);
  const largestResult=margin?null:f.rows.reduce((a,b)=>a.profit>=b.profit?a:b);
  const isSplit=f.status==='segments';
  const cell=(value,max,isResult=false)=>`<span class="financial-value">${value<0?'−':''}${amount(Math.abs(value))}${margin&&isResult?'%':''}</span>${isResult&&!margin?`<span class="financial-outcome">${value<0?'Loss':value===0?'Break-even':'Positive result'}</span>`:''}<span class="financial-bar${value<0?' is-loss':''}${isResult?' is-result':''}" aria-hidden="true"><span style="width:${Math.min(100,Math.abs(value)/max*100)}%"></span></span>`;
  return `<section class="financial-panel" id="financials" aria-labelledby="financial-title"><div class="eyebrow">FIGURES FROM COMPANY DISCLOSURES</div><h3 id="financial-title">${isSplit?'Which businesses bring in sales and earnings?':'What the company totals tell us.'}</h3><p class="financial-period">${escape(c.name)}<br>${escape(f.period)}</p><div class="financial-tags"><span>${escape(f.basis)}</span><span>${escape(f.coverage)}</span></div><p class="financial-explainer">${escape(incomeDefinition)} The earnings measure below is <strong>${escape(f.profitMetric)}</strong>. ${escape(f.definition)}</p><p class="financial-unit">Amounts in ${escape(f.unit)}${margin?'; reported margins in %':''}. 1 crore = 1,00,00,000 rupees. Values rounded for display.</p><table class="financial-table"><caption class="sr-only">${escape(c.name)} ${escape(revenueLabel)} and ${escape(f.profitMetric)} for ${escape(f.period)}; ${escape(f.basis)}</caption><thead><tr><th scope="col">${isSplit?'Business':'Reporting scope'}</th><th scope="col">${escape(revenueLabel)}<br><small>₹ crore</small></th><th scope="col">${escape(f.profitMetric)}<br><small>${margin?'%':'₹ crore'}</small></th></tr></thead><tbody>${f.rows.map(r=>`<tr><th scope="row">${escape(r.name)}</th><td>${cell(r.revenue,margin?maxRevenue:amountScale)}</td><td>${cell(margin?r.margin:r.profit,resultScale,true)}</td></tr>`).join('')}</tbody>${f.revenueTotal!==undefined&&isSplit?`<tfoot><tr><th scope="row">${escape(f.revenueTotalLabel||'Reported segment total')}</th><td>${amount(f.revenueTotal)}</td><td>${f.profitTotal!==undefined?`${f.profitTotal<0?'−':''}${amount(Math.abs(f.profitTotal))}${f.profitTotal<0?' (loss)':''}`:'Not aggregated'}</td></tr></tfoot>`:''}</table><p class="financial-scale">${margin?revenueLabel+' bars scale to the largest income row; margin bars run from 0% to 100%. Profit amounts are not estimated.':revenueLabel+' and result bars use the same ₹ crore scale. Red bars and a minus sign identify a loss, not a smaller positive profit.'}</p>${isSplit?`<div class="financial-leaders"><div><span>LARGEST REVENUE</span><strong>${escape(largestSales.name)}</strong></div><div><span>${margin?'HIGHEST REPORTED MARGIN':'HIGHEST REPORTED RESULT'}</span><strong>${escape(margin?f.rows.reduce((a,b)=>a.margin>=b.margin?a:b).name:largestResult.name)}</strong></div></div>`:''}<div class="financial-takeaway"><h4>What this helps you understand</h4><p>${escape(f.insight)}</p><small>Company Notebook explanation, based on the figures above.</small></div><p class="financial-reconciliation">${escape(f.notes)}</p><details class="financial-notes"><summary>Why the profit measure matters</summary><p>Check the reporting scope and definition before comparing figures. Definitions differ between companies; EBITDA, segment results and profit after tax are not interchangeable. Profit also differs from cash generated. These are dated disclosures, not live figures.</p></details><p class="source-note financial-source"><a href="${escape(f.source)}" target="_blank" rel="noopener">${escape(f.sourceLabel)} ↗</a>${f.announcement?` · <a href="${escape(f.announcement)}" target="_blank" rel="noopener">Company results announcement ↗</a>`:''}<br>${escape(f.location)}<br>Financial source checked ${escape(f.checked)}. This check covers the financial figures above.</p></section>`;
 }
 return {render};
})();
